import{_ as r,C as s,o as c,c as d,a6 as a,E as t,j as i,a as l}from"./chunks/framework.5dd0l9Wo.js";const T=JSON.parse('{"title":"Race Conditions","description":"Time-of-check to time-of-use windows, limit overruns, multi-endpoint races, and single-packet attacks.","frontmatter":{"title":"Race Conditions","description":"Time-of-check to time-of-use windows, limit overruns, multi-endpoint races, and single-packet attacks."},"headers":[],"relativePath":"race-conditions/index.md","filePath":"race-conditions/index.md"}'),p={name:"race-conditions/index.md"};function u(m,e,h,g,b,f){const n=s("LabGroup"),o=s("TopicComplete");return c(),d("div",null,[e[0]||(e[0]=a(`<h1 id="race-conditions" tabindex="-1">Race Conditions <a class="header-anchor" href="#race-conditions" aria-label="Permalink to &quot;Race Conditions&quot;">​</a></h1><p class="wd-section-lede">A race condition is a correctness bug that appears only when two operations interleave. In web applications it usually means a check and a write are not atomic, so the check can pass more times than the rule allows.</p><div class="wd-callout"><p><strong>The model.</strong> Find a pair: <code>if (allowed)</code> followed by <code>do_it()</code>. If another request can run between them, the invariant is broken. The window may be microseconds, which is why exploitation is about <em>concurrency</em> rather than speed.</p></div><h2 id="toctou-in-one-diagram" tabindex="-1">TOCTOU in one diagram <a class="header-anchor" href="#toctou-in-one-diagram" aria-label="Permalink to &quot;TOCTOU in one diagram&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>request A:  check balance ≥ price  ──┐</span></span>
<span class="line"><span>request B:  check balance ≥ price  ──┤ both pass before either write</span></span>
<span class="line"><span>request A:  balance -= price         │</span></span>
<span class="line"><span>request B:  balance -= price         │  balance is now negative</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The database may be ACID, but the application-level check and update are two statements. Without a transaction, a row lock, or a conditional update (<code>UPDATE ... WHERE balance &gt;= price</code>), the rule is not enforced.</p><h2 id="limit-overruns" tabindex="-1">Limit overruns <a class="header-anchor" href="#limit-overruns" aria-label="Permalink to &quot;Limit overruns&quot;">​</a></h2><p>The canonical case: a one-use coupon, a one-time gift card, or a vote limit. Send the same request many times simultaneously; if more than one succeeds, the state was read before any write landed.</p>`,8)),t(n,{ids:"race-conditions-lab-race-conditions-limit-overrun, race-conditions-lab-race-conditions-bypassing-rate-limits"}),e[1]||(e[1]=a('<details class="details custom-block"><summary>🔬 Under the Hood: single-packet attack</summary><p>HTTP/1.1 requests on separate connections arrive at slightly different times, so a wide race window is needed. The <strong>single-packet attack</strong> sends the final byte of many requests in one TCP packet, so a server that processes them in parallel sees them arrive together. HTTP/2 multiplexing achieves the same with many streams in one connection.</p><p>Turbo Intruder implements this by opening connections, pre-sending all but the last byte, then releasing them together. The practical effect is to shrink the arrival jitter from milliseconds to microseconds, which is often the difference between a failed and a successful race.</p></details><h2 id="multi-endpoint-and-single-endpoint-races" tabindex="-1">Multi-endpoint and single-endpoint races <a class="header-anchor" href="#multi-endpoint-and-single-endpoint-races" aria-label="Permalink to &quot;Multi-endpoint and single-endpoint races&quot;">​</a></h2><p>A <strong>multi-endpoint</strong> race uses different endpoints that touch shared state: add an item in one request while applying a discount in another. A <strong>single-endpoint</strong> race sends the same request with different values and relies on the server&#39;s internal ordering.</p>',3)),t(n,{ids:"race-conditions-lab-race-conditions-multi-endpoint, race-conditions-lab-race-conditions-single-endpoint"}),e[2]||(e[2]=i("h2",{id:"time-sensitive-and-partial-construction",tabindex:"-1"},[l("Time-sensitive and partial construction "),i("a",{class:"header-anchor",href:"#time-sensitive-and-partial-construction","aria-label":'Permalink to "Time-sensitive and partial construction"'},"​")],-1)),e[3]||(e[3]=i("p",null,"Some tokens or objects are valid only during a short window, or are constructed in stages. Racing a password-reset token against its invalidation, or registering an account while its confirmation record is half-built, can bypass the intended state.",-1)),t(n,{ids:"race-conditions-lab-race-conditions-exploiting-time-sensitive-vulnerabilities, race-conditions-lab-race-conditions-partial-construction"}),e[4]||(e[4]=a('<details class="details custom-block"><summary>⚙️ Engine Variations: where atomicity actually comes from</summary><ul><li><strong>PostgreSQL / MySQL:</strong> <code>SELECT ... FOR UPDATE</code>, unique constraints, and <code>UPDATE ... WHERE</code> are atomic; a read-then-write in application code is not.</li><li><strong>MongoDB:</strong> single-document updates are atomic; read-modify-write across documents is not. <code>findOneAndUpdate</code> with a condition is the primitive.</li><li><strong>Redis:</strong> <code>INCR</code>, <code>SETNX</code>, and Lua scripts are atomic; <code>GET</code> then <code>SET</code> is not.</li><li><strong>File-based counters:</strong> no atomicity without <code>flock</code>; even then, NFS semantics differ.</li><li><strong>Serverless:</strong> multiple instances mean in-process locks are useless; use the datastore.</li></ul><p>The fix is almost always to move the check into the same atomic operation as the write.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Make invariants database constraints, not application checks. Use conditional updates that report affected rows. Wrap multi-step state changes in transactions with the right isolation level. Make one-time tokens single-use with a unique constraint. Test with concurrent requests, not sequential ones.</p></div>',2)),t(o,{"topic-id":"race-conditions",label:"Mark race conditions complete"})])}const v=r(p,[["render",u]]);export{T as __pageData,v as default};
